import type { Metadata } from "next";
import { site } from "@/content/site";

type PageMetadataInput = {
  title: string;
  description: string;
  path: string;
  image?: { url: string; alt: string };
};

// Per-page metadata with its own canonical URL and Open Graph block.
// Canonical/OG URLs are set per page (never in the root layout), otherwise
// every child page would inherit the home page's canonical URL.
//
// Defining `openGraph` on a page replaces the parent's, including any image
// generated by an opengraph-image file, so every page states its image here.
const defaultImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name} — ${site.role}`,
};

export function pageMetadata({ title, description, path, image }: PageMetadataInput): Metadata {
  const images = [image ? { ...defaultImage, ...image } : defaultImage];
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_US",
      siteName: site.name,
      url: path,
      title: `${title} — ${site.name}`,
      description,
      images,
    },
    twitter: {
      card: "summary_large_image",
      title: `${title} — ${site.name}`,
      description,
      images,
    },
  };
}
